@ ================================================================
@ PiTrex ARM32 builtins
@ ================================================================

@ pitrex_wait_recal() — frame sync via v_WaitRecal(), then fix scale=127
.global pitrex_wait_recal
.type pitrex_wait_recal, %function
pitrex_wait_recal:
    push    {lr}
    bl      v_WaitRecal
    mov     r0, #127
    bl      v_setScale
    pop     {pc}
    .ltorg

@ pitrex_set_intensity(r0=brightness 0-127)
.global pitrex_set_intensity
.type pitrex_set_intensity, %function
pitrex_set_intensity:
    push    {lr}
    bl      v_setBrightness
    pop     {pc}
    .ltorg

@ pitrex_move(r0=x, r1=y) — move beam, no draw
.global pitrex_move
.type pitrex_move, %function
pitrex_move:
    push    {r4, r5, r6, r7, lr}
    mov     r4, #127
    mul     r4, r0, r4          @ r4 = new_x * 127
    mov     r5, #127
    mul     r5, r1, r5          @ r5 = new_y * 127
    ldr     r6, =PITREX_CUR_X
    ldr     r0, [r6]            @ r0 = cur_x
    ldr     r7, =PITREX_CUR_Y
    ldr     r1, [r7]            @ r1 = cur_y
    mov     r2, r4              @ x1 = new_x
    mov     r3, r5              @ y1 = new_y
    mov     r12, #0
    push    {r12}               @ brightness=0 (5th arg)
    bl      v_directDraw32
    add     sp, sp, #4          @ pop 5th arg
    str     r4, [r6]            @ PITREX_CUR_X = new_x
    str     r5, [r7]            @ PITREX_CUR_Y = new_y
    pop     {r4, r5, r6, r7, pc}
    .ltorg

@ pitrex_draw_line(r0=x0, r1=y0, r2=x1, r3=y1, [sp+0]=brightness)
.global pitrex_draw_line
.type pitrex_draw_line, %function
pitrex_draw_line:
    push    {r4, lr}
    ldr     r4, [sp, #8]        @ brightness
    mov     r12, #127
    mul     r0, r0, r12         @ x0 * 127
    mul     r1, r1, r12         @ y0 * 127
    mul     r2, r2, r12         @ x1 * 127
    mul     r3, r3, r12         @ y1 * 127
    push    {r4}               @ brightness as 5th arg
    bl      v_directDraw32
    add     sp, sp, #4
    pop     {r4, pc}
    .ltorg

@ pitrex_draw_line_rel(r0=dx, r1=dy, r2=brightness)
.global pitrex_draw_line_rel
.type pitrex_draw_line_rel, %function
pitrex_draw_line_rel:
    push    {r4, r5, r6, r7, lr}
    mov     r4, #127
    mul     r4, r0, r4          @ r4 = dx * 127
    mov     r5, #127
    mul     r5, r1, r5          @ r5 = dy * 127
    mov     r6, r2              @ r6 = brightness
    ldr     r7, =PITREX_CUR_X
    ldr     r0, [r7]            @ r0 = cur_x
    ldr     r12, =PITREX_CUR_Y
    ldr     r1, [r12]           @ r1 = cur_y
    add     r2, r0, r4          @ r2 = new_x
    add     r3, r1, r5          @ r3 = new_y
    push    {r6}               @ brightness as 5th arg
    bl      v_directDraw32
    add     sp, sp, #4
    ldr     r1, =PITREX_CUR_X
    ldr     r2, [r1]
    add     r2, r2, r4
    str     r2, [r1]            @ PITREX_CUR_X += dx*100
    ldr     r1, =PITREX_CUR_Y
    ldr     r2, [r1]
    add     r2, r2, r5
    str     r2, [r1]            @ PITREX_CUR_Y += dy*100
    pop     {r4, r5, r6, r7, pc}
    .ltorg

@ pitrex_draw_vector(r0=asset_ptr, r1=ox, r2=oy)
.global pitrex_draw_vector
.type pitrex_draw_vector, %function
pitrex_draw_vector:
    push    {r4, r5, r6, r7, r8, r9, lr}
    mov     r4, r0              @ asset header ptr
    mov     r3, #127
    mul     r6, r1, r3          @ ox*127
    mul     r7, r2, r3          @ oy*127
    ldr     r5, [r4], #4        @ path_count
    mov     r8, #0
dv_path_loop:
    cmp     r8, r5
    bge     dv_done
    ldr     r9, [r4], #4        @ r9 = path data ptr
    ldr     r0, =PITREX_CUR_X
    str     r6, [r0]
    ldr     r0, =PITREX_CUR_Y
    str     r7, [r0]
    add     r9, r9, #1          @ skip intensity byte
    ldrsb   r1, [r9], #1        @ dy = y_start
    ldrsb   r0, [r9], #1        @ dx = x_start
    add     r9, r9, #2          @ skip 2 hdr padding bytes
    mov     r2, #0              @ brightness 0 = move only
    push    {r4, r5, r6, r7, r8, r9}
    bl      pitrex_draw_line_rel
    pop     {r4, r5, r6, r7, r8, r9}
dv_seg_loop:
    ldrb    r0, [r9], #1        @ marker (0xFF=draw, 0x02=end)
    cmp     r0, #2
    beq     dv_seg_done
    ldrsb   r1, [r9], #1        @ dy
    ldrsb   r0, [r9], #1        @ dx
    mov     r2, #127            @ full brightness
    push    {r4, r5, r6, r7, r8, r9}
    bl      pitrex_draw_line_rel
    pop     {r4, r5, r6, r7, r8, r9}
    b       dv_seg_loop
dv_seg_done:
    add     r8, r8, #1
    b       dv_path_loop
dv_done:
    pop     {r4, r5, r6, r7, r8, r9, pc}
    .ltorg

@ pitrex_draw_vector_ex(r0=asset_ptr, r1=ox, r2=oy, r3=mirror, [sp]=intensity)
.global pitrex_draw_vector_ex
.type pitrex_draw_vector_ex, %function
pitrex_draw_vector_ex:
    push    {r4, r5, r6, r7, r8, r9, lr}    @ 28 bytes
    mov     r4, r0              @ asset header ptr
    mov     r5, r1              @ ox
    mov     r6, r2              @ oy
    mov     r7, r3              @ mirror flag
    ldr     r8, [sp, #28]       @ intensity (5th arg)
    ldr     r9, [r4], #4        @ path_count
    push    {r9}                @ [sp+0] = path_count
    mov     r9, #0
    push    {r9}                @ [sp+0] = path_idx, [sp+4] = path_count
dvex_path_loop:
    ldr     r0, [sp]            @ path_idx
    ldr     r1, [sp, #4]        @ path_count
    cmp     r0, r1
    bge     dvex_done
    ldr     r9, [r4], #4        @ r9 = path data ptr
    mov     r0, #127
    mul     r1, r5, r0          @ ox*127
    ldr     r2, =PITREX_CUR_X
    str     r1, [r2]
    mul     r1, r6, r0          @ oy*127
    ldr     r2, =PITREX_CUR_Y
    str     r1, [r2]
    add     r9, r9, #1          @ skip intensity byte
    ldrsb   r1, [r9], #1        @ dy = y_start
    ldrsb   r0, [r9], #1        @ dx = x_start
    add     r9, r9, #2          @ skip 2 hdr padding bytes
    cmp     r7, #1
    it      eq
    rsbeq   r0, r0, #0          @ mirror dx
    mov     r2, #0              @ move only
    push    {r4, r5, r6, r7, r8, r9}
    bl      pitrex_draw_line_rel
    pop     {r4, r5, r6, r7, r8, r9}
dvex_seg_loop:
    ldrb    r0, [r9], #1
    cmp     r0, #2
    beq     dvex_seg_done
    ldrsb   r1, [r9], #1        @ dy
    ldrsb   r0, [r9], #1        @ dx
    cmp     r7, #1
    it      eq
    rsbeq   r0, r0, #0
    mov     r2, r8              @ intensity
    push    {r4, r5, r6, r7, r8, r9}
    bl      pitrex_draw_line_rel
    pop     {r4, r5, r6, r7, r8, r9}
    b       dvex_seg_loop
dvex_seg_done:
    ldr     r0, [sp]
    add     r0, r0, #1
    str     r0, [sp]            @ path_idx++
    b       dvex_path_loop
dvex_done:
    add     sp, sp, #8          @ pop path_idx + path_count
    pop     {r4, r5, r6, r7, r8, r9, pc}
    .ltorg

@ pitrex_j1_x() → r0 = X axis (-127..127)
.global pitrex_j1_x
.type pitrex_j1_x, %function
pitrex_j1_x:
    ldr     r1, =currentJoy1X
    ldrsb   r0, [r1]
    bx      lr
    .ltorg

@ pitrex_j1_y() → r0 = Y axis (-127..127)
.global pitrex_j1_y
.type pitrex_j1_y, %function
pitrex_j1_y:
    ldr     r1, =currentJoy1Y
    ldrsb   r0, [r1]
    bx      lr
    .ltorg

@ pitrex_j1_btn1() → r0=1 if pressed, 0 otherwise (bit 0)
.global pitrex_j1_btn1
.type pitrex_j1_btn1, %function
pitrex_j1_btn1:
    ldr     r1, =currentButtonState
    ldr     r0, [r1]
    lsr     r0, r0, #0
    and     r0, r0, #1
    bx      lr
    .ltorg

@ pitrex_j1_btn2() → r0=1 if pressed, 0 otherwise (bit 1)
.global pitrex_j1_btn2
.type pitrex_j1_btn2, %function
pitrex_j1_btn2:
    ldr     r1, =currentButtonState
    ldr     r0, [r1]
    lsr     r0, r0, #1
    and     r0, r0, #1
    bx      lr
    .ltorg

@ pitrex_j1_btn3() → r0=1 if pressed, 0 otherwise (bit 2)
.global pitrex_j1_btn3
.type pitrex_j1_btn3, %function
pitrex_j1_btn3:
    ldr     r1, =currentButtonState
    ldr     r0, [r1]
    lsr     r0, r0, #2
