@ pitrex_j1_btn4() → r0=1 if pressed, 0 otherwise (bit 3)
.global pitrex_j1_btn4
.type pitrex_j1_btn4, %function
pitrex_j1_btn4:
    ldr     r1, =currentButtonState
    ldr     r0, [r1]
