    bx      lr
    .ltorg

@ pitrex_print_text(r0=x, r1=y, r2=str_ptr)
.global pitrex_print_text
.type pitrex_print_text, %function
pitrex_print_text:
    push    {r4, r5, r6, lr}
    mov     r4, r0
    mov     r5, r1
    mov     r6, r2
    mov     r0, #0
    mov     r1, #0
    bl      v_directMove32
    mov     r0, r4              @ VPy_x
    mov     r1, r5              @ VPy_y
    mov     r2, r6              @ str_ptr
    ldr     r3, =PITREX_TEXT_SIZE
    ldr     r3, [r3]
    cmp     r3, #0
    it eq
    moveq   r3, #5
    sub     r1, r1, #8          @ baseline = top - cap_height (VPy units)
    mov     r12, #127
    mul     r0, r0, r12          @ r0  = x*127
    asr     r0, r0, #7           @ r0  = x*127/128 (sign-preserving)
    mul     r1, r1, r12          @ r1  = y*127
    asr     r1, r1, #7           @ r1  = y*127/128 (sign-preserving)
    mov     r12, #0x50
    push    {r12}
    bl      v_printString
    add     sp, sp, #4
    pop     {r4, r5, r6, pc}
    .ltorg

@ pitrex_draw_rect(r0=x, r1=y, r2=w, r3=h) 5th=[sp]=brightness
.global pitrex_draw_rect
.type pitrex_draw_rect, %function
pitrex_draw_rect:
    push    {r4, r5, r6, r7, lr}
    mov     r4, r0          @ x (left)
    mov     r5, r1          @ y (bottom)
    mov     r6, r2          @ w
    mov     r7, r3          @ h
    mov     r0, #127
    mul     r4, r4, r0
    mul     r5, r5, r0
    mul     r6, r6, r0
    mul     r7, r7, r0
    mov     r0, r4
    mov     r1, r5
    add     r2, r4, r6
    mov     r3, r5
    ldr     r12, [sp, #20]
    push    {r12}
    bl      v_directDraw32
    add     sp, sp, #4
    add     r0, r4, r6
    mov     r1, r5
    add     r2, r4, r6
    add     r3, r5, r7
    ldr     r12, [sp, #20]
    push    {r12}
    bl      v_directDraw32
    add     sp, sp, #4
    add     r0, r4, r6
    add     r1, r5, r7
    mov     r2, r4
    add     r3, r5, r7
    ldr     r12, [sp, #20]
    push    {r12}
    bl      v_directDraw32
    add     sp, sp, #4
    mov     r0, r4
    add     r1, r5, r7
    mov     r2, r4
    mov     r3, r5
    ldr     r12, [sp, #20]
    push    {r12}
    bl      v_directDraw32
    add     sp, sp, #4
    pop     {r4, r5, r6, r7, pc}

@ pitrex_draw_filled_rect(r0=x, r1=y, r2=w, r3=h, [sp+0]=brightness)
.global pitrex_draw_filled_rect
.type pitrex_draw_filled_rect, %function
pitrex_draw_filled_rect:
    push    {r4, r5, r6, r7, r8, r9, lr}
    mov     r4, r0          @ x (left)
    mov     r5, r1          @ y (bottom)
    mov     r6, r2          @ w
    mov     r7, r3          @ h
    ldr     r8, [sp, #28]   @ brightness ([sp+7regs*4])
    push    {r8}            @ brightness as 5th arg
    bl      pitrex_draw_rect
    add     sp, sp, #4
    mov     r9, #127
    mul     r4, r4, r9      @ x_s
    mul     r5, r5, r9      @ y_s (bottom)
    mul     r6, r6, r9      @ w_s
    mul     r7, r7, r9      @ h_s
    add     r9, r9, r9, lsl #1   @ scan step = 3 * 127 = 381
    add     r0, r5, r9      @ scan_y = y + step
.Lfill_loop:
    add     r1, r5, r7      @ top = y_s + h_s
    cmp     r0, r1
    bge     .Lfill_done     @ exit when scan_y >= top
    mov     r1, r0          @ y0 = scan_y
    add     r2, r4, r6      @ x1 = x_s + w_s
    mov     r3, r0          @ y1 = scan_y
    push    {r0}            @ save scan_y for after the call
    mov     r0, r4          @ x0 = x_s
    push    {r8}            @ brightness as 5th arg ([sp+0])
    bl      v_directDraw32
    add     sp, sp, #4      @ pop brightness
    pop     {r0}            @ restore scan_y
    add     r0, r0, r9      @ scan_y += step
    b       .Lfill_loop
.Lfill_done:
    pop     {r4, r5, r6, r7, r8, r9, pc}
    .ltorg

@ pitrex_draw_polygon(r0=n, r1=intensity, r2=x0, r3=y0, stack=x1,y1,x2,y2,...)
.global pitrex_draw_polygon
.type pitrex_draw_polygon, %function
pitrex_draw_polygon:
    mov     r12, sp
    push    {r4, r5, r6, r7, r8, r9, r10, r11, lr}
    mov     r4, r0          @ n
    mov     r5, #127        @ scale
    mov     r6, r1          @ brightness
    mul     r7, r2, r5      @ x0_s
    mul     r8, r3, r5      @ y0_s
    ldr     r0, [r12, #0]   @ x1 raw
    mul     r9, r0, r5      @ x1_s
    ldr     r0, [r12, #4]   @ y1 raw
    mul     r10, r0, r5     @ y1_s
    push    {r9, r10}       @ save v1 endpoint (cur_x, cur_y)
    mov     r0, r7
    mov     r1, r8
    mov     r2, r9
    mov     r3, r10
    push    {r6}            @ brightness ([sp+0])
    bl      v_directDraw32
    add     sp, sp, #4
    pop     {r9, r10}       @ r9=cur_x=x1_s, r10=cur_y=y1_s
    mov     r11, #2
.Lpoly_loop:
    cmp     r11, r4
    bge     .Lpoly_close
    mov     r0, r11, lsl #1 @ 2k
    sub     r0, r0, #2      @ 2k-2
    lsl     r0, r0, #2      @ (2k-2)*4
    add     r0, r0, #36     @ + callee-save frame (9*4)
    ldr     r2, [sp, r0]    @ xk raw (sp-relative, avoids clobbered r12)
    mul     r0, r2, r5      @ xk_s → r0  (Rd=r0 != Rm=r2)
    mov     r1, r11, lsl #1 @ 2k
    sub     r1, r1, #1      @ 2k-1
    lsl     r1, r1, #2      @ (2k-1)*4
    add     r1, r1, #36     @ + callee-save frame
    ldr     r2, [sp, r1]    @ yk raw (sp-relative)
    mul     r1, r2, r5      @ yk_s → r1  (Rd=r1 != Rm=r2)
    push    {r0, r1}        @ save new xk_s, yk_s
    mov     r2, r0
    mov     r3, r1
    mov     r0, r9
    mov     r1, r10
    push    {r6}            @ brightness
    bl      v_directDraw32
    add     sp, sp, #4
    pop     {r9, r10}       @ r9=xk_s, r10=yk_s
    add     r11, r11, #1
    b       .Lpoly_loop
.Lpoly_close:
    mov     r0, r9
    mov     r1, r10
    mov     r2, r7
    mov     r3, r8
    push    {r6}            @ brightness
    bl      v_directDraw32
    add     sp, sp, #4
    pop     {r4, r5, r6, r7, r8, r9, r10, r11, pc}
    .ltorg

