    ldrsb   r0, [r1]
    cmp     r0, #32
    bgt     1f
    cmn     r0, #32
    blt     2f
    mov     r0, #0
    bx      lr
1:  mov     r0, #1
    bx      lr
2:  mvn     r0, #0
    bx      lr
    .ltorg

