@ pitrex_update_level() — advance GP object physics
.global pitrex_update_level
.type pitrex_update_level, %function
pitrex_update_level:
    push    {r4, r5, r6, r7, r8, r9, lr}
    ldr     r9, =LEVEL_DATA_PTR
    ldr     r9, [r9]
    cmp     r9, #0
    beq     .Lul_done
    ldr     r4, =LEVEL_GP_COUNT
    ldr     r4, [r4]            @ r4 = gpCount
    cmp     r4, #0
    beq     .Lul_done
    ldrsh   r5, [r9, #4]        @ yMin
    ldrsh   r6, [r9, #6]        @ yMax
    ldr     r7, [r9, #16]       @ gpObjectsPtr (ROM)
    ldr     r8, =LEVEL_GP_BUF   @ mutable buf
.Lul_loop:
    ldrb    r0, [r7, #6]        @ flags byte
    tst     r0, #1              @ bit0 = physics enable
    beq     .Lul_next
    ldrsh   r1, [r8]            @ buf.x
    ldrsh   r2, [r8, #2]        @ buf.y
    ldrsh   r3, [r8, #4]        @ buf.vx
    ldrsh   r12, [r8, #6]       @ buf.vy
    tst     r0, #2              @ bit1 = gravity
    beq     .Lul_nograv
    sub     r12, r12, #1        @ vy -= 1 (downward gravity)
    cmp     r12, #-32
    movlt   r12, #-32
.Lul_nograv:
    add     r1, r1, r3          @ x += vx
    add     r2, r2, r12         @ y += vy
    cmp     r2, r5
    movlt   r2, r5
    movlt   r12, #0
    cmp     r2, r6
    movgt   r2, r6
    movgt   r12, #0
    strh    r1, [r8]            @ buf.x
    strh    r2, [r8, #2]        @ buf.y
    strh    r3, [r8, #4]        @ buf.vx (unchanged)
    strh    r12, [r8, #6]       @ buf.vy
.Lul_next:
    add     r7, r7, #16         @ next ROM object
    add     r8, r8, #8          @ next buf entry
    subs    r4, r4, #1
    bne     .Lul_loop
.Lul_done:
    pop     {r4, r5, r6, r7, r8, r9, pc}
    .ltorg

@ pitrex_draw_vector_3d(r0=x, r1=y, r2=z, r3=asset_ptr) — perspective
.global pitrex_draw_vector_3d
.type pitrex_draw_vector_3d, %function
pitrex_draw_vector_3d:
    push    {r4, r5, r6, r7, lr}
    mov     r4, r0              @ x
    mov     r5, r1              @ y
    mov     r6, r2              @ z
    mov     r7, r3              @ asset_ptr
    cmp     r6, #0
    ble     .Ldv3d_done
    mov     r0, r4
    ldr     r1, =100
    mul     r0, r0, r1          @ x * 100
    mov     r1, r6
    bl      __aeabi_idiv        @ r0 = screen_x
    mov     r4, r0              @ save screen_x
    mov     r0, r5
    ldr     r1, =100
    mul     r0, r0, r1          @ y * 100
    mov     r1, r6
    bl      __aeabi_idiv        @ r0 = screen_y
    mov     r5, r0              @ save screen_y
    push    {r4, r5}            @ save screen coords
    mov     r8, #127
    push    {r8}                @ 5th arg: intensity=127
    mov     r3, #0              @ mirror=0
    mov     r2, r5              @ oy = screen_y
    mov     r1, r4              @ ox = screen_x
    mov     r0, r7              @ asset_ptr
    bl      pitrex_draw_vector_ex
    add     sp, sp, #4          @ pop intensity
    pop     {r4, r5}            @ pop screen coords (discard)
.Ldv3d_done:
    pop     {r4, r5, r6, r7, pc}
    .ltorg

@ pitrex_print_number(r0=x, r1=y, r2=value) — print decimal integer
.global pitrex_print_number
.type pitrex_print_number, %function
pitrex_print_number:
    push    {r4, r5, r6, r7, r8, r9, lr}
    mov     r4, r0          @ x
    mov     r5, r1          @ y
    mov     r6, r2          @ value
    sub     sp, sp, #8
    mov     r7, sp          @ buf ptr
    mov     r9, #0          @ is_negative = false
    cmp     r6, #0
    bge     pn_positive
    mov     r9, #1          @ is_negative = true
    mov     r0, #45         @ '-' ASCII (font renders as space-advance)
    strb    r0, [r7]
    add     r7, r7, #1
    rsb     r6, r6, #0      @ abs(r6)
pn_positive:
    @ digit 0: /1000
    ldr     r8, =1000
    mov     r0, r6
    mov     r1, r8
    bl      __aeabi_idivmod  @ r0=quot, r1=rem
    add     r0, r0, #48
    strb    r0, [r7]
    add     r7, r7, #1
    mov     r6, r1
    @ digit 1: /100
    ldr     r8, =100
    mov     r0, r6
    mov     r1, r8
    bl      __aeabi_idivmod  @ r0=quot, r1=rem
    add     r0, r0, #48
    strb    r0, [r7]
    add     r7, r7, #1
    mov     r6, r1
    @ digit 2: /10
    ldr     r8, =10
    mov     r0, r6
    mov     r1, r8
    bl      __aeabi_idivmod  @ r0=quot, r1=rem
    add     r0, r0, #48
    strb    r0, [r7]
    add     r7, r7, #1
    mov     r6, r1
    @ digit 3: ones
    add     r0, r6, #48
    strb    r0, [r7]
    add     r7, r7, #1
    mov     r0, #0
    strb    r0, [r7]
    mov     r0, #0
    mov     r1, #0
    bl      v_directMove32
    ldr     r3, =PITREX_TEXT_SIZE
    ldr     r3, [r3]
    cmp     r3, #0
    it eq
    moveq   r3, #5
    cmp     r9, #0
    beq     pn_print_str
    ldr     r12, =127
    mul     r0, r4, r12         @ x0_px = VPy_x * 127 (Rd≠Rm ✓)
    sub     r2, r5, #8          @ VPy_y - 8 (cap_height offset)
    mul     r1, r2, r12         @ y_baseline_px (Rd≠Rm ✓)
    add     r1, r1, r3, lsl #2  @ + 4*textSize
    add     r1, r1, r3, lsl #1  @ + 2*textSize → y_mid = baseline+6*ts
    add     r2, r0, r3, lsl #3  @ x1 = x0 + 8*textSize
    mov     r3, r1              @ y1 = y0 (horizontal line)
    mov     r12, #0x50
    push    {r12}
    bl      v_directDraw32
    add     sp, sp, #4
    ldr     r3, =PITREX_TEXT_SIZE
    ldr     r3, [r3]
    cmp     r3, #0
    it eq
    moveq   r3, #5
pn_print_str:
    mov     r0, r4          @ x
    mov     r1, r5          @ y
    mov     r2, sp          @ buf ptr
    sub     r1, r1, #8          @ baseline = top - cap_height (VPy units)
    mov     r12, #127
    mul     r0, r0, r12          @ r0  = x*127
    asr     r0, r0, #7           @ r0  = x*127/128
    mul     r1, r1, r12          @ r1  = y*127
    asr     r1, r1, #7           @ r1  = y*127/128
    mov     r12, #0x50
    push    {r12}
    bl      v_printString
    add     sp, sp, #4
    add     sp, sp, #8
    pop     {r4, r5, r6, r7, r8, r9, pc}
    .ltorg

@ pitrex_draw_anim(r0 = ARM ptr to _ANIM_NAME data block, r1 = ox, r2 = oy)
.global pitrex_draw_anim
.type pitrex_draw_anim, %function
pitrex_draw_anim:
    push    {r4, r5, r6, r7, r8, r9, r10, r11, lr}
    mov     r4, r0                      @ anim header ptr
    mov     r10, r1                     @ save ox
    mov     r11, r2                     @ save oy
    ldr     r5, =PITREX_ANIM_STATE_BUF
    ldrb    r6, [r5]                    @ frame_idx
    ldrb    r7, [r5, #1]                @ ticks_left (0=uninitialized)
    ldrb    r8, [r4, #2]                @ base_ref_count
    cmp     r8, #0
    beq     par_tick
    add     r9, r4, #4                  @ first base_ref word-ptr
par_base_loop:
    push    {r8, r9}
    ldr     r0, [r9]                    @ ARM ptr to vec data
    mov     r1, r10                     @ ox
    mov     r2, r11                     @ oy
    bl      pitrex_draw_vector
    pop     {r8, r9}
    add     r9, r9, #4                  @ next base_ref ptr
    subs    r8, r8, #1
    bne     par_base_loop
par_tick:
    cmp     r7, #0
    beq     par_init_frame              @ first call: init frame 0
    subs    r7, r7, #1
    bgt     par_draw                    @ still ticking: draw current frame
    ldrb    r8, [r4]                    @ frame_count
    add     r6, r6, #1
    cmp     r6, r8
    blt     par_no_wrap
    ldrb    r9, [r4, #1]                @ loop flag
    cmp     r9, #0
    beq     par_freeze
    mov     r6, #0                      @ loop: wrap to frame 0
par_no_wrap:
    strb    r6, [r5]                    @ save new frame_idx
par_init_frame:
    ldrb    r8, [r4, #3]                @ frame_table_offset
    lsl     r9, r6, #2                  @ frame_idx * 4
    add     r9, r9, r8                  @ offset to frame table entry
    ldr     r9, [r4, r9]                @ ARM ptr to frame data
    ldrb    r7, [r9]                    @ duration_ticks
    cmp     r7, #0
    movle   r7, #1                      @ clamp to min 1
    strb    r7, [r5, #1]                @ save ticks_left
    b       par_draw_vecs
par_freeze:
    sub     r6, r6, #1                  @ stay on last frame
    strb    r6, [r5]
    mov     r7, #1
    strb    r7, [r5, #1]
    b       par_draw_frame
par_draw:
    strb    r7, [r5, #1]                @ save decremented ticks
par_draw_frame:
    ldrb    r8, [r4, #3]                @ frame_table_offset
    lsl     r9, r6, #2                  @ frame_idx * 4
    add     r9, r9, r8
    ldr     r9, [r4, r9]                @ ARM ptr to frame data
par_draw_vecs:
    ldrb    r8, [r9, #1]                @ vec_ref_count
    cmp     r8, #0
    beq     par_done
    add     r9, r9, #4                  @ skip duration+count+2-byte pad
    mov     r6, r8                      @ loop counter
par_vec_loop:
    push    {r6, r9}
    ldr     r0, [r9]                    @ ARM ptr to vec data
    mov     r1, r10                     @ ox
    mov     r2, r11                     @ oy
    bl      pitrex_draw_vector
    pop     {r6, r9}
    add     r9, r9, #4                  @ next vec ptr
    subs    r6, r6, #1
    bne     par_vec_loop
par_done:
    pop     {r4, r5, r6, r7, r8, r9, r10, r11, pc}
    .ltorg

.bss
.balign 4
PITREX_ANIM_STATE_BUF: .space 2
.text

@ --- function SHUFFLE ---
