@ vpy_uart_puts(r0=str_ptr) — write null-terminated string via UART
.type vpy_uart_puts, %function
vpy_uart_puts:
    push    {r4, lr}
    mov     r4, r0
.Lputs_loop:
    ldrb    r0, [r4], #1
    cmp     r0, #0
    beq     .Lputs_done
    bl      RPI_AuxUartWrite
    b       .Lputs_loop
.Lputs_done:
    pop     {r4, pc}

.Lstr_start:  .asciz "VPy PiTrex starting\r\n"
.Lstr_vinit:  .asciz "vectrexinit OK\r\n"
    .ltorg

